<?php
namespace App\Http\Controllers\Dashboard;
use App\Http\Controllers\Controller; use App\Http\Controllers\Dashboard\Concerns\RedirectsAfterSave; use Illuminate\Http\Request;
class ChecklistController extends Controller { use RedirectsAfterSave; public function index(Request $request) { $registration=$request->user()->registrations()->with('checklistItems.checklistItem')->latest()->firstOrFail(); return view('dashboard.checklist', compact('registration')); } public function update(Request $request) { $request->validate(['return_to'=>['nullable','url']]); $ids=$request->input('completed', []); $registration=$request->user()->registrations()->latest()->firstOrFail(); foreach ($registration->checklistItems as $item) $item->update(['completed_at'=>in_array($item->id, $ids) ? now() : null]); return $this->redirectAfterSave($request,'Checklist saved'); } }
